import Foundation

#if FRAMEJOB_DEV_TOOLS
/// Every compositor's requests in this process, counted at four points (the export hang of
/// codec export C5's fix pass, `designs/codec-export.md`): `asked` as AVFoundation hands a
/// request to `startRequest`, `begun` as its block starts on the render queue, `done` as
/// that block returns, `answered` beside every answer the request is given — and
/// `cancelAll` per `cancelAllPendingVideoCompositionRequests`. A stuck export reads which
/// gap is open: asked but never begun, begun but still serving, served but never answered,
/// or none (AVFoundation never asked).
///
/// Read by the `export_sheet` dev tool and by `encoder_limit_probe.swift`'s trace; compiled
/// only under the flag (spec §11 V-1), so Distribution counts nothing.
enum CompositorRequestCounts {
    struct Snapshot: Equatable {
        let asked: Int
        let begun: Int
        let done: Int
        let answered: Int
        let cancelAll: Int
    }

    private static let lock = NSLock()
    nonisolated(unsafe) private static var counts = (
        asked: 0, begun: 0, done: 0, answered: 0, cancelAll: 0)

    static func asked() { bump { $0.asked += 1 } }
    static func begun() { bump { $0.begun += 1 } }
    static func done() { bump { $0.done += 1 } }
    static func answered() { bump { $0.answered += 1 } }
    static func cancelledAll() { bump { $0.cancelAll += 1 } }

    static var snapshot: Snapshot {
        lock.lock()
        defer { lock.unlock() }
        return Snapshot(
            asked: counts.asked, begun: counts.begun, done: counts.done,
            answered: counts.answered, cancelAll: counts.cancelAll)
    }

    private static func bump(
        _ change: (inout (asked: Int, begun: Int, done: Int, answered: Int, cancelAll: Int))
            -> Void
    ) {
        lock.lock()
        change(&counts)
        lock.unlock()
    }
}
#endif

