import AppKit

#if FRAMEJOB_DEV_TOOLS
/// `export_sheet` — a dev tool (the export hang of codec export C5's fix pass, spec §11
/// V-1..V-2): puts up File ▸ Export…'s progress sheet without its save panel, reads it, and
/// closes it once it is over, so a script can run a sheet beside the Export Queue the way a
/// person does (`tools/proof/export_hang_soak.py`).
///
/// **`begin` is the save panel's own call.** The settings are `export`'s
/// (`ReelExport.settings` with the `encoder_speed` override, the URL through
/// `destinationURL` and `requireFolder`), and the sheet is put up by
/// `EditorViewController.beginExport(settings:to:)`, which is exactly what Export…'s save
/// panel calls. The sheet books in the encoder ledger in `viewDidAppear`, after `begin`
/// returns, so `booked` may be empty and a caller polls `status` for the booking.
/// `physical_memory` sets `ExportEncoderLedger.shared.physicalMemory` first (0 restores
/// `ProcessInfo`'s), the knob `encoder_limit_probe.swift` turns in process.
///
/// **`status`** answers the sheet's state, its status line and bar, the ledger's bookings and
/// every compositor's request counts (`CompositorRequestCounts`). **`close`** dismisses a
/// finished sheet and refuses a running one: a running export is stopped by its Cancel.
///
/// It runs on MAIN (not in `devOffMainTools`): it waits for nothing.
extension AgentServer {

    private enum ExportSheetAction: String, CaseIterable {
        case begin, status, close
    }

    func exportSheet(_ a: [String: Any]) throws -> String {
        guard let action = try enumArg(a, "action", ExportSheetAction.self) else {
            throw ToolError(message: "Missing required argument: action")
        }
        let document = try target(a)
        guard let editor = editor(document), let window = editor.view.window else {
            let name = Self.path(of: document) ?? document.displayName ?? "Untitled"
            throw ToolError(
                message: "The project \(name) has no window: export_sheet puts its sheet on the "
                    + "editor window.")
        }
        let sheet = editor.presentedViewControllers?
            .compactMap { $0 as? ExportProgressSheetController }.first
        switch action {
        case .begin:
            return try beginExportSheet(a, document, editor, window)
        case .status:
            return try jsonResult(Self.exportSheetStatus(sheet))
        case .close:
            guard let sheet else {
                throw ToolError(message: "No export sheet is up on \"\(window.title)\".")
            }
            guard sheet.devReading.finished else {
                throw ToolError(
                    message: "The export sheet is still writing; close refuses a running "
                        + "sheet.")
            }
            sheet.dismiss(nil)
            return try jsonResult(["closed": true])
        }
    }

    private func beginExportSheet(
        _ a: [String: Any], _ document: ProjectDocument, _ editor: EditorViewController,
        _ window: NSWindow
    ) throws -> String {
        let presetID = try requiredString(a, "preset")
        let path = try requiredString(a, "path")
