    path = Path(path)
    return path.parents[2] if path.parent.name == "MacOS" else path


def executable(app):
    """A bundle's executable: `Contents/MacOS/` and the bundle's own stem."""
    app = Path(app)
    return app / "Contents/MacOS" / app.stem


